import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Remove duplicates by seq (at-least-once delivery)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Sort by seq to process in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 3: Apply replay guard and filter events
    # For each order, skip events where seq <= last_seq in target_state
    target_state_dict = {}
    if len(target_state) > 0:
        for _, row in target_state.iterrows():
            target_state_dict[row["order_id"]] = {
                "status": row["status"],
                "amount": row["amount"],
                "last_seq": row["last_seq"]
            }

    filtered_events = []
    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]

        # Replay guard: skip if order exists and seq <= last_seq
        if order_id in target_state_dict:
            if seq <= target_state_dict[order_id]["last_seq"]:
                continue

        filtered_events.append(event)

    if not filtered_events:
        filtered_events = pd.DataFrame(columns=cdc_events.columns)
    else:
        filtered_events = pd.DataFrame(filtered_events)

    # Step 4: Apply events in order
    state = target_state_dict.copy()
    last_op_per_order = {}  # Track the last operation for tombstone detection

    for _, event in filtered_events.iterrows():
        order_id = event["order_id"]
        op = event["op"]
        seq = event["seq"]
        status = event["status"]
        amount = event["amount"]

        if op == "I":
            # Insert or update
            state[order_id] = {
                "status": status,
                "amount": amount,
                "last_seq": seq
            }
            last_op_per_order[order_id] = ("I", seq)

        elif op == "U":
            # Update or create
            if order_id not in state:
                state[order_id] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq
                }
            else:
                state[order_id]["status"] = status
                # Only update amount if not NULL
                if pd.notna(amount):
                    state[order_id]["amount"] = amount
                state[order_id]["last_seq"] = seq
            last_op_per_order[order_id] = ("U", seq)

        elif op == "D":
            # Delete
            if order_id in state:
                del state[order_id]
            last_op_per_order[order_id] = ("D", seq)

    # Step 5: Build new_state
    new_state_rows = []
    for order_id, record in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": record["status"],
            "amount": record["amount"],
            "last_seq": record["last_seq"]
        })

    if new_state_rows:
        new_state = pd.DataFrame(new_state_rows)
    else:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])

    new_state = new_state.astype({
        "order_id": "int64",
        "status": "object",
        "amount": "float64",
        "last_seq": "int64"
    })

    # Step 6: Build tombstones
    # Include orders that had a row in target_state or were created/modified
    tombstone_rows = []
    all_touched_orders = set(target_state_dict.keys()) | set(last_op_per_order.keys())

    for order_id in all_touched_orders:
        if order_id in last_op_per_order:
            op, seq = last_op_per_order[order_id]
            if op == "D":
                tombstone_rows.append({
                    "order_id": order_id,
                    "deleted_seq": seq
                })

    if tombstone_rows:
        tombstones = pd.DataFrame(tombstone_rows)
    else:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])

    tombstones = tombstones.astype({
        "order_id": "int64",
        "deleted_seq": "int64"
    })

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
